Single-threaded by design: no wall clock, no threads, no hash-based
ordering. Ties at the same timestamp break by priority (lower first),
then by the order in which events were scheduled.
"""

import heapq


class _Event:
    __slots__ = ("time", "priority", "seq", "callback", "args", "handle")

    def __init__(self, time, priority, seq, callback, args, handle):
        self.time = time
        self.priority = priority
        self.seq = seq
        self.callback = callback
        self.args = args
        self.handle = handle


class Handle:
    """Opaque token returned by Scheduler.schedule."""

    __slots__ = ("event", "armed")

    def __init__(self, event):
        self.event = event
        self.armed = True


class Scheduler:
    def __init__(self):
        self._heap = []
        self._seq = 0
        self._now = 0

    @property
    def now(self):
        return self._now

    @property
    def pending(self):
        return sum(1 for e in self._heap if e.handle.armed)

    def schedule(self, delay, callback, *args, priority=0):
        if delay < 0:
            raise ValueError("delay must be >= 0")
        self._seq += 1
        handle = Handle(None)
        event = _Event(self._now + delay, priority, self._seq, callback, args, handle)
        handle.event = event
        heapq.heappush(self._heap, (event.time, event.priority, event.seq, event))
        return handle

    def cancel(self, handle):
        if handle.armed:
            handle.armed = False
            self._prune()
            return True
        return False

    def _prune(self):
        self._heap = [entry for entry in self._heap if entry[3].handle.armed]
        heapq.heapify(self._heap)

    def _pop_due(self, horizon):
        """Pop and return the next armed event at or before horizon, or None."""
        while self._heap:
            _, _, _, event = self._heap[0]
            if not event.handle.armed:
                heapq.heappop(self._heap)
                continue
            if event.time > horizon:
                return None
            heapq.heappop(self._heap)
            return event
        return None

    def _fire(self, event):
        event.handle.armed = False
        self._now = max(self._now, event.time)
        event.callback(*event.args)

    def run_until(self, t):
        if t < self._now:
            raise ValueError("cannot run_until a time in the past")
        while True:
            event = self._pop_due(t)
            if event is None:
                break
            self._fire(event)
        self._now = t

    def run_next(self):
        event = self._pop_due(float("inf"))
        if event is None:
            return None
        self._fire(event)
        return self.time_of_last = None
