class Autocomplete:
    """Accumulates weighted search terms and suggests ranked matches."""

    def __init__(self):
        self._weights = {}

    @staticmethod
    def _normalize(term):
        if not isinstance(term, str):
            raise ValueError("term must be a string")
        normalized = term.strip().lower()
        if not normalized:
            raise ValueError("term must not be empty or whitespace-only")
        return normalized

    def insert(self, term, weight=1):
        key = self._normalize(term)
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:
            raise ValueError("weight must be a positive int")
        self._weights[key] = self._weights.get(key, 0) + weight

    def suggest(self, prefix, limit=5):
        if not isinstance(prefix, str):
            raise ValueError("prefix must be a string")
        p = prefix.strip().lower()
        if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
            return []
        matches = [t for t in self._weights if t.startswith(p)]
        matches.sort(key=lambda t: (-self._weights[t], t))
        return matches[:limit]

    def count(self, term):
        try:
            key = self._normalize(term)
        except ValueError:
            return 0
        return self._weights.get(key, 0)

    def delete(self, term):
        try:
            key = self._normalize(term)
        except ValueError:
            return False
        if key in self._weights:
            del self._weights[key]
            return True
        return False

    def __contains__(self, term):
        try:
            return self._normalize(term) in self._weights
        except ValueError:
            return False

    def __len__(self):
        return len(self._weights)
