if (-not ('BriefKit.Renderer' -as [type])) {
    Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace BriefKit
{
    public static class Renderer
    {
        public static string Build(string path)
        {
            if (!File.Exists(path))
            {
                throw new FileNotFoundException("briefkit: log not found: " + path);
            }

            StringBuilder sb = new StringBuilder(1 << 25);
            sb.Append("shift brief\n");

            long idx = 0;
            long skipped = 0;
            Dictionary<string, long> levels = new Dictionary<string, long>(StringComparer.Ordinal);

            using (StreamReader sr = new StreamReader(path))
            {
                string line;
                while ((line = sr.ReadLine()) != null)
                {
                    if (string.IsNullOrWhiteSpace(line)) { continue; }

                    string[] f = line.Split(' ');
                    if (f.Length != 5 || f[0].Length == 0 || f[1].Length == 0 ||
                        f[2].Length == 0 || f[3].Length == 0 || f[4].Length == 0)
                    {
                        skipped++;
                        continue;
                    }

                    idx++;
                    sb.Append(idx.ToString("D7", System.Globalization.CultureInfo.InvariantCulture)).Append(' ');
                    sb.Append(f[2].PadRight(5)).Append(' ');
                    sb.Append(f[0]).Append('/').Append(f[1]).Append(' ');
                    sb.Append(f[3]).Append("ms").Append(' ');
                    sb.Append(f[4]).Append('\n');

                    long c;
                    levels.TryGetValue(f[2], out c);
                    levels[f[2]] = c + 1;
                }
            }

            sb.Append("entries: ").Append(idx).Append('\n');
            sb.Append("skipped: ").Append(skipped).Append('\n');

            if (levels.Count > 0)
            {
                List<string> names = new List<string>(levels.Keys);
                names.Sort(StringComparer.Ordinal);
                for (int i = 0; i < names.Count; i++)
                {
                    sb.Append("level ").Append(names[i]).Append(": ").Append(levels[names[i]]).Append('\n');
                }
            }

            return sb.ToString();
        }
    }
}
'@
}

