[call] {"name":"Write","arguments":{"content":"# loadsheet.ps1 -- freight load-sheet helpers for the northbound runs.
#
# Dot-source this file, then:
#
#   $rows = @(Read-LoadRows -Path loads.csv)
#   Format-LoadSheet -Rows $rows -Title 'northbound am'
#
# loads.csv columns: id,dest,kg,pri   (kg/pri integers)
#
# Loads travel between helpers as typed records with properties
# Id, Dest, Kg, Pri (kg/pri real [int]s).

Set-StrictMode -Version Latest

function Read-LoadRows {
    # Parse the dispatch CSV into typed records, file-order preserved.
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "file not found: $Path"
    }
    $leaf = Split-Path -Leaf $Path
    $rows = @()
    $line = 1   # the header sits on line 1
    foreach ($rec in @(Import-Csv -LiteralPath $Path)) {
        $line++
        $kg = 0
        $pri = 0
        if ([string]::IsNullOrEmpty($rec.id) -or
            -not [int]::TryParse($rec.kg, [ref]$kg) -or
            -not [int]::TryParse($rec.pri, [ref]$pri)) {
            throw "${leaf}: bad row $line"
        }
        $rows += [pscustomobject]@{
            Id   = [string]$rec.id
            Dest = [string]$rec.dest
            Kg   = $kg
            Pri  = $pri
        }
    }
    return $rows
}

function Select-HeavyLoads {
    # Keep the loads at or above the weight cutoff. Accepts records
    # via -Rows or from the pipeline.
    param(
        [Parameter(ValueFromPipeline)][psobject[]]$Rows,
        [Parameter(Mandatory)][int]$MinKg
    )
    process {
        foreach ($row in $Rows) {
            if ($row.Kg -ge $MinKg) { $row }
        }
    }
}

function Select-Destination {
    # Keep the loads bound for one destination (exact, case-sensitive).
    # Accepts records via -Rows or from the pipeline.
    param(
        [Parameter(ValueFromPipeline)][psobject[]]$Rows,
        [Parameter(Mandatory)][string]$Dest
    )
    process {
        foreach ($row in $Rows) {
            if ($row.Dest -ceq $Dest) { $row }
        }
    }
}

function Measure-Loads {
    # Totals for a set of loads: one record with Count, TotalKg, MaxKg
    # (all [int]; all zero for an empty set). Accepts records via
    # -Rows or from the pipeline.
    param([Parameter(ValueFromPipeline)][psobject[]]$Rows)
    $count = 0
    $total = 0
    $max = 0
    foreach ($row in @($Rows)) {
        $count++
        $total += $row.Kg
        if ($row.Kg -gt $max) { $max = $row.Kg }
    }
    return [pscustomobject]@{
        Count   = $count
        TotalKg = $total
        MaxKg   = $max
    }
}

function Format-LoadSheet {
    # Render the printable sheet the yard crew works from. Returns one
    # string; the caller decides where it goes. Accepts records via
    # -Rows or from the pipeline. Output is byte-identical to the
    # historic rendering.
    param(
        [Parameter(ValueFromPipeline)][psobject[]]$Rows,
        [Parameter(Mandatory)][string]$Title
    )
    begin { $all = @() }
    process { $all += @($Rows) }
    end {
        $lines = @("LOAD SHEET: $Title")
        if ($null -eq $all -or $all.Count -eq 0) {
            $lines += 'no loads'
            return (($lines -join "`n") + "`n")
        }
